-- Demo data: every login gets the same sample board, dated around its own "today".
-- Generated from the original FluidCRM sample (src/data/deals.js in the design repo).

-- Fills one login's board. Internal: called by crm_session() on first sign-in and by reset_demo().
CREATE OR REPLACE FUNCTION __APP_SCHEMA__.seed_demo_for(target uuid) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = __APP_SCHEMA__, pg_temp AS $$
DECLARE
  tz text := coalesce((SELECT timezone FROM __APP_SCHEMA__.members WHERE user_id = target), 'Asia/Kolkata');
  today date := (now() AT TIME ZONE tz)::date;
  me_name text := coalesce((SELECT name FROM __APP_SCHEMA__.members WHERE user_id = target), 'Me');
  company uuid;
  deal uuid;
  ev uuid;
  first_contact uuid;
  contact uuid;
BEGIN
  PERFORM set_config('app.via', 'seed', true);
  -- Meridian Technologies

  -- Cloudnine Retail

  -- Vantage FinServ

  -- Astra Health

  -- Nexa Infra

  -- Prava Tech

  UPDATE __APP_SCHEMA__.members SET demo_seeded_at = now() WHERE user_id = target;
  PERFORM set_config('app.via', '', true);
END $$;
REVOKE EXECUTE ON FUNCTION __APP_SCHEMA__.seed_demo_for(uuid) FROM PUBLIC, anon, authenticated;

-- "Reset demo": wipes the caller's own board and refills it.
CREATE OR REPLACE FUNCTION __APP_SCHEMA__.reset_demo() RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path = __APP_SCHEMA__, pg_temp AS $$
BEGIN
  IF NOT __APP_SCHEMA__.is_active_member() THEN
    RAISE EXCEPTION 'You don''t have access to this CRM.' USING ERRCODE = '42501';
  END IF;
  DELETE FROM __APP_SCHEMA__.activity_log WHERE user_id = auth.uid();
  DELETE FROM __APP_SCHEMA__.companies WHERE user_id = auth.uid();
  PERFORM __APP_SCHEMA__.seed_demo_for(auth.uid());
END $$;
REVOKE EXECUTE ON FUNCTION __APP_SCHEMA__.reset_demo() FROM PUBLIC, anon;

-- First sign-in also fills the board.
CREATE OR REPLACE FUNCTION __APP_SCHEMA__.crm_session_seeded() RETURNS jsonb
LANGUAGE plpgsql SECURITY DEFINER SET search_path = __APP_SCHEMA__, pg_temp AS $$
DECLARE
  session jsonb := __APP_SCHEMA__.crm_session();
BEGIN
  IF session IS NOT NULL AND session ->> 'status' = 'active' AND NOT (session ->> 'demo_seeded')::boolean THEN
    PERFORM __APP_SCHEMA__.seed_demo_for(auth.uid());
    session := session || jsonb_build_object('demo_seeded', true);
  END IF;
  RETURN session;
END $$;
REVOKE EXECUTE ON FUNCTION __APP_SCHEMA__.crm_session_seeded() FROM PUBLIC, anon;
